fn bitwise_or(a: Vec<u8>, b: Vec<u8>) -> Vec<u8> {
    // Since we assume `a` and `b` have the same length, we can assert it for safety.
    assert_eq!(a.len(), b.len(), "Input vectors must have the same length");

    // Consume `a` and `b` by value, zip their iterators, apply bitwise OR, and collect into a new Vec.
    a.into_iter()
     .zip(b.into_iter())
     .map(|(x, y)| x | y)
     .collect()
}

